  --font-sans: Source Sans Pro, system-ui, -apple-system, sans-serif;
  --font-serif: Crimson Text, Georgia, serif;
  --font-mono: Menlo, monospace;
  --font-display: Playfair Display, Georgia, serif;
  --radius: .5rem; /* 8px */
  --shadow-2xs: 0px 1px 2px 0px hsl(40 20% 10% / 0.05);
  --shadow-xs: 0px 1px 2px 0px hsl(40 20% 10% / 0.08);
  --shadow-sm: 0px 1px 3px 0px hsl(40 20% 10% / 0.10), 0px 1px 2px -1px hsl(40 20% 10% / 0.10);
  --shadow: 0px 2px 4px -1px hsl(40 20% 10% / 0.10), 0px 4px 6px -1px hsl(40 20% 10% / 0.10);
  --shadow-md: 0px 4px 6px -1px hsl(40 20% 10% / 0.10), 0px 2px 4px -2px hsl(40 20% 10% / 0.10);
  --shadow-lg: 0px 10px 15px -3px hsl(40 20% 10% / 0.10), 0px 4px 6px -4px hsl(40 20% 10% / 0.10);
  --shadow-xl: 0px 20px 25px -5px hsl(40 20% 10% / 0.10), 0px 8px 10px -6px hsl(40 20% 10% / 0.10);
  --shadow-2xl: 0px 25px 50px -12px hsl(40 20% 10% / 0.15);
  --tracking-normal: 0em;
  --spacing: 0.25rem;

  /* Automatically computed borders - intensity can be controlled by the user by the --opaque-button-border-intensity setting */

